#include "generic_bridge_arithmetic.hpp"
using AKRow=std::vector<F>;
using AKMatrix=std::vector<AKRow>;
F ak_base(const Z& z){return F(CFPoly{z});}
P ak_embed(const CFPoly& p){std::vector<F> out;for(auto& c:p.c)out.push_back(ak_base(c));return P(out);}
std::string ak_key(const G& g){return g.u.key()+"|"+g.v.key();}
G ak_frob(const G& g){auto u=g.u.c,v=g.v.c;for(auto& z:u)z=z.power(prime);for(auto& z:v)z=z.power(prime);return {P(u),P(v)};}
AKMatrix ak_kernel(const AKMatrix& matrix,int width,int& rank){std::map<int,AKRow> rows;for(auto row:matrix){require(int(row.size())==width,"extension constraint width");for(auto& [p,r]:rows){F c=row[p];if(c!=F(0))for(int j=p;j<width;++j)row[j]=row[j]-c*r[j];}int p=0;while(p<width&&row[p]==F(0))++p;if(p==width)continue;F inverse=row[p].inv();for(int j=p;j<width;++j)row[j]=row[j]*inverse;rows.emplace(p,row);}AKMatrix out;for(int free=0;free<width;++free)if(!rows.count(free)){AKRow v(size_t(width),F(0));v[free]=F(1);for(auto it=rows.rbegin();it!=rows.rend();++it){F sum;for(int j=it->first+1;j<width;++j)sum=sum+it->second[j]*v[j];v[it->first]=-sum;}out.push_back(v);}rank=int(rows.size());for(auto& v:out)for(auto& r:matrix){F sum;for(int j=0;j<width;++j)sum=sum+r[j]*v[j];require(sum==F(0),"extension nullspace direct replay");}return out;}
struct AKSource {
    inline static P support;
    P a;
    AKSource(long n=0):a{F(n)}{}
    explicit AKSource(P p):a(p%support){}
    AKSource operator+(const AKSource& b)const{return AKSource(a+b.a);}
    AKSource operator-()const{return AKSource(-a);}
    AKSource operator-(const AKSource& b)const{return AKSource(a-b.a);}
    AKSource operator*(const AKSource& b)const{return AKSource((a*b.a)%support);}
    AKSource inv()const{auto [g,s,t]=xgcd(a,support);require(g.degree()==0,"Fp8 source coefficient denominator unit");AKSource r(s.scale(g.at(0).inv()));require(*this*r==AKSource(1),"Fp8 source inverse replay");return r;}
    AKSource operator/(const AKSource& b)const{return *this*b.inv();}
    bool operator==(const AKSource& b)const{return a==b.a;}
    bool operator!=(const AKSource& b)const{return !(*this==b);}
};
using AKP=Poly<AKSource>;
AKSource ak_at(const P& p,const AKSource& x){AKSource r;for(int i=p.degree();i>=0;--i)r=r*x+AKSource(P{p.at(i)});return r;}
AKSource ak_field(const Json& row,const AKSource& x,const AKSource& y){auto a=ak_at(ak_embed(pc_read_poly(row.at("a"))),x),b=ak_at(ak_embed(pc_read_poly(row.at("b"))),x),c=ak_at(ak_embed(pc_read_poly(row.at("c"))),x);return (a+b*y)/c;}
AKRow ak_flat(const AKP& p,int d){AKRow out(size_t(3*d),F(0));for(int j=0;j<3;++j)for(int i=0;i<d;++i)out[size_t(j*d+i)]=p.at(j).a.at(i);return out;}
AKRow ak_solve(const AKMatrix& columns,const AKRow& rhs){int n=int(rhs.size());require(int(columns.size())==n,"Fp8 square power basis");AKMatrix rows(size_t(n),AKRow(size_t(n+1),F(0)));for(int i=0;i<n;++i){for(int j=0;j<n;++j)rows[i][j]=columns[j][i];rows[i][n]=rhs[i];}for(int j=0;j<n;++j){int p=j;while(p<n&&rows[p][j]==F(0))++p;require(p<n,"Fp8 full image power basis");std::swap(rows[p],rows[j]);F inv=rows[j][j].inv();for(int k=j;k<=n;++k)rows[j][k]=rows[j][k]*inv;for(int i=0;i<n;++i)if(i!=j){F c=rows[i][j];if(c!=F(0))for(int k=j;k<=n;++k)rows[i][k]=rows[i][k]-c*rows[j][k];}}AKRow out,replay(size_t(n),F(0));for(int i=0;i<n;++i)out.push_back(rows[i][n]);for(int j=0;j<n;++j)for(int i=0;i<n;++i)replay[i]=replay[i]+out[j]*columns[j][i];require(replay==rhs,"Fp8 power basis solve replay");return out;}
P ak_power(P a,int n,const P& u){P out{F(1)};for(int i=0;i<n;++i)out=(out*a)%u;return out;}
P ak_curve(const EBPoly& f,const P& u,const P& v){P x{F(0),F(1)},out;for(auto& [e,c]:f.terms)out=(out+(ak_power(x,e[0],u)*ak_power(v,e[1],u)).scale(ak_base(c)))%u;return out;}
struct AKImage {P u{F(1)},v;int degree=0;};
AKImage ak_image(const G& source,const Json& global,const EBPoly& f){source.check();AKImage out;out.degree=source.u.degree();require(out.degree>=1&&out.degree<=3,"Fp8 positive source divisor degree");AKSource::support=source.u;AKSource x(P{F(0),F(1)}),y(source.v);std::vector<AKSource> uc,vc;for(auto& c:global.at("U").arr)uc.push_back(ak_field(c,x,y));for(auto& c:global.at("V").arr)vc.push_back(ak_field(c,x,y));AKP u(uc),v(vc),t{AKSource(0),AKSource(1)},power{AKSource(1)};require(u.degree()==3&&u.at(3)==AKSource(1),"Fp8 monic target cubic");AKMatrix basis;int n=3*out.degree;for(int k=0;k<n;++k){basis.push_back(ak_flat(power,out.degree));power=(power*t)%u;}auto relation=ak_solve(basis,ak_flat(power,out.degree)),value=ak_solve(basis,ak_flat(v,out.degree));for(auto& c:relation)c=-c;relation.push_back(F(1));out.u=P(relation);out.v=P(value);auto evaluate=[&](const P& p){AKP z;for(int i=p.degree();i>=0;--i)z=(z*t+AKP{AKSource(P{p.at(i)})})%u;return z;};require(evaluate(out.u).degree()<0&&evaluate(out.v)==v,"Fp8 closed image reconstruction");require(ak_curve(f,out.u,out.v).degree()<0,"Fp8 image quartic incidence");require(ak_curve(f,out.u,out.v+P{F(1)}).degree()>=0,"changed Fp8 image y rejected");return out;}
CFPoly ak_residual_y(const CFPoly& u,const EBPoly& f,const EBPoly& g,int depth=0){require(depth<=3,"residual cubic splitting depth");CFResidue::support=u;try{auto d=std::get<0>(xgcd(cf_residue_y(f),cf_residue_y(g)));require(d.degree()==1,"residual linear y chart");return (-d.at(0)/d.at(1)).a;}catch(const CFSplit& s){auto p=s.factor.monic(),q=u.exact(p).monic();require(p.degree()>0&&q.degree()>0,"proper residual support split");auto a=ak_residual_y(p,f,g,depth+1),b=ak_residual_y(q,f,g,depth+1);return cf_crt(p,a,q,b);}}
struct AKPrincipal {
    QuarticKM& km;
    std::vector<int> reference;
    std::vector<Monomial> mons;
    CFPoly residual_u,residual_v;
    EBPoly g0;
    explicit AKPrincipal(QuarticKM& k,const Json& formal,const EBPoly& f):km(k){for(auto& c:formal.at("seed_indices").arr)reference.push_back(c.integer());require(reference.size()==3,"actual-kernel reference triple");mons=monomial_basis(3);require(mons.size()==10,"ten cubic sections");km.mons=mons;Space constraints;CFPoly reference_u{Z(1)};for(int index:reference){auto& p=km.points.at(size_t(index));auto jets=km.monomial_jets(p);for(int j=0;j<3;++j){Vector row;for(auto& v:jets)row.push_back(v[j]);constraints.push_back(row);}for(int j=0;j<3;++j)reference_u=reference_u*CFPoly{-Z(p.x),Z(1)};}auto basis=nullspace(constraints,10);require(basis.size()==1&&row_basis(constraints,10).size()==9,"unique cubic through triple reference");for(int i=0;i<10;++i)g0.add(mons[i],basis[0][i]);auto resultant=cf_resultant(f,g0);require(resultant.degree()==12,"complete affine reference cubic intersection degree12");residual_u=resultant.exact(reference_u).monic();require(residual_u.degree()==3&&cf_gcd(residual_u,reference_u).degree()==0&&cf_gcd(residual_u,cf_derivative(residual_u)).degree()==0,"complete disjoint squarefree residual3");residual_v=ak_residual_y(residual_u,f,g0);require(cf_evaluate(f,residual_u,residual_v).degree()<0&&cf_evaluate(g0,residual_u,residual_v).degree()<0,"reference residual cubic/quartic incidence");}
    void closed(AKMatrix& rows,const P& u,const P& v)const{int n=u.degree();AKMatrix constraints(size_t(n),AKRow(10,F(0)));P x{F(0),F(1)};for(int j=0;j<10;++j){auto e=mons[j];auto q=(ak_power(x,e[0],u)*ak_power(v,e[1],u))%u;for(int i=0;i<n;++i)constraints[i][j]=q.at(i);}rows.insert(rows.end(),constraints.begin(),constraints.end());}
    P cubic_at(const AKRow& coefficients,const P& u,const P& v)const{P x{F(0),F(1)},r;for(int j=0;j<10;++j){auto e=mons[j];r=(r+(ak_power(x,e[0],u)*ak_power(v,e[1],u)).scale(coefficients[j]))%u;}return r;}
    AKMatrix test(const AKImage& image,int& rank)const{require(image.degree>=0&&image.degree<=3,"principal test source degree");AKMatrix rows;if(image.degree){require(std::get<0>(xgcd(image.u,ak_embed(residual_u))).degree()==0,"image and residual supports disjoint");closed(rows,image.u,image.v);}for(int index:reference){auto& p=km.points.at(size_t(index));if(image.degree<3)require(image.u.eval(ak_base(Z(p.x)))!=F(0),"padded reference support disjoint");auto jets=km.monomial_jets(p);for(int k=0;k<3-image.degree;++k){AKRow row;for(auto& j:jets)row.push_back(ak_base(j[k]));rows.push_back(row);}}closed(rows,ak_embed(residual_u),ak_embed(residual_v));require(rows.size()==12,"complete degree12 principal constraints");auto kernel=ak_kernel(rows,10,rank);for(auto& c:kernel){if(image.degree)require(cubic_at(c,image.u,image.v).degree()<0,"principal cubic actual closed image incidence");require(cubic_at(c,ak_embed(residual_u),ak_embed(residual_v)).degree()<0,"principal cubic actual residual incidence");}return kernel;}
};
void ak_emit_field(const F& c){cf_emit_poly(c.a);}
void ak_emit_poly(const P& p){std::cout<<'[';for(int i=0;i<=p.degree();++i){if(i)std::cout<<',';ak_emit_field(p.at(i));}std::cout<<']';}
void ak_emit_row(const AKRow& row){std::cout<<'[';for(size_t i=0;i<row.size();++i){if(i)std::cout<<',';ak_emit_field(row[i]);}std::cout<<']';}
int main(int argc,char** argv){try{
    require(argc==5,"usage: actual_kernel kernel3-study global.json formal.json generic-bridge.json");std::string root=argv[1];initialize_cover(read_json(root+"/inputs/p192-d7-prym.json"));auto global=read_json(argv[2]),formal=read_json(argv[3]),bridge=read_json(argv[4]),model=read_json(root+"/evidence/p192-d7-kernel3-plane-quartic.json"),points=read_json(root+"/evidence/destination-relations-v2/result.json"),weil=read_json(root+"/evidence/weil3-v2/result.json"),actual=read_json(root+"/evidence/final-kernel-check/actual-cover-torsion.json");EBPoly f;for(auto& c:model.at("terms").arr){auto e=c.at("exponents");f.add({e.arr[0].integer(),e.arr[1].integer()},Z(mpz_class(c.at("coefficient").scalar)));}std::vector<G> kernel;std::map<std::string,int> index;for(auto& row:weil.at("functions").arr){G p{polynomial(row.at("P_U")),polynomial(row.at("P_V"))};p.check();int i=int(kernel.size());require(index.emplace(ak_key(p),i).second,"distinct actual source kernel members");if(i)require(!(p==G{})&&p.times(3)==G{},"actual nonzero order3 source member");else require(p==G{},"first recorded kernel identity");kernel.push_back(p);}require(kernel.size()==27,"actual kernel cardinality27");int closure=0;for(auto& a:kernel)for(auto& b:kernel){require(index.count(ak_key(a.add(b))),"actual kernel full closure");++closure;}std::vector<int> frobenius;for(auto& p:kernel){auto q=ak_frob(p);q.check();auto hit=index.find(ak_key(q));require(hit!=index.end(),"actual kernel Frobenius membership");frobenius.push_back(hit->second);}G outside;int outside_index=-1;for(size_t i=0;i<actual.at("basis").arr.size();++i){auto& row=actual.at("basis").arr[i];G p{polynomial(row.at("U")),polynomial(row.at("V"))};p.check();if(!index.count(ak_key(p))){require(!(p==G{})&&p.times(3)==G{},"outside source order3 control");outside=p;outside_index=int(i);break;}}require(outside_index>=0,"actual torsion outside recorded kernel");std::cerr<<"27 distinct kernel members,729 closure sums,order3 and Frobenius checks pass\n";
    QuarticKM km(model,points);AKPrincipal principal(km,formal,f);int zero_rank=0;auto zero=principal.test(AKImage{},zero_rank);require(zero_rank==9&&zero.size()==1,"reference principal zero control");auto& public_row=bridge.at("images").arr[0];G public_source{ak_embed(pc_read_poly(public_row.at("source_U"))),ak_embed(pc_read_poly(public_row.at("source_V")))};auto public_image=ak_image(public_source,global,f);require(public_image.u==ak_embed(pc_read_poly(public_row.at("target_U")))&&public_image.v==ak_embed(pc_read_poly(public_row.at("target_V"))),"Fp8 evaluator equals original-field public image");int public_rank=0;require(principal.test(public_image,public_rank).empty()&&public_rank==10,"known nonzero public principal control");std::cerr<<"residual3,known zero/nonzero and base-field evaluator controls pass\n";
    std::vector<AKImage> images(1);std::vector<AKRow> cubics(1);std::vector<int> ranks(1,9);for(int i=1;i<27;++i){auto image=ak_image(kernel[i],global,f);int rank=0;auto sections=principal.test(image,rank);require(rank==9&&sections.size()==1,"recorded kernel image principal");images.push_back(image);cubics.push_back(sections[0]);ranks.push_back(rank);std::cerr<<"actual kernel member "<<i<<" image degree="<<image.u.degree()<<" principal rank="<<rank<<'\n';}auto control_image=ak_image(outside,global,f);int outside_rank=0;require(principal.test(control_image,outside_rank).empty()&&outside_rank==10,"nonkernel torsion image nonzero");int frobenius_checks=0;for(int i=1;i<27;++i){auto& a=images[i];auto& b=images[frobenius[i]];require(a.u.degree()==b.u.degree()&&a.v.degree()==b.v.degree(),"actual image Frobenius shape");for(int j=0;j<=a.u.degree();++j){require(a.u.at(j).power(prime)==b.u.at(j),"actual image support Frobenius");++frobenius_checks;}for(int j=0;j<=a.v.degree();++j){require(a.v.at(j).power(prime)==b.v.at(j),"actual image y Frobenius");++frobenius_checks;}}
    std::cout<<"{\"scope\":\"P192-kernel3-actual-global-kernel-containment\",\"standing\":\"producer-unverified\",\"recorded_cardinality\":27,\"closure_checks\":"<<closure<<",\"nonzero_order3_checks\":26,\"principal_nonzero_member_checks\":26,\"reference_principal_rank\":"<<zero_rank<<",\"public_nonzero_rank\":"<<public_rank<<",\"outside_basis_index\":"<<outside_index<<",\"outside_nonzero_rank\":"<<outside_rank<<",\"actual_image_Frobenius_checks\":"<<frobenius_checks<<",\"exact_kernel_degree_established\":false,\"dual_checked\":false,\"field_modulus\":";cf_emit_poly(modulus);std::cout<<",\"reference_cubic\":";eb_emit_poly(std::cout,principal.g0);std::cout<<",\"residual_U\":";cf_emit_poly(principal.residual_u);std::cout<<",\"residual_V\":";cf_emit_poly(principal.residual_v);std::cout<<",\"members\":[";for(int i=1;i<27;++i){if(i>1)std::cout<<',';std::cout<<"{\"index\":"<<i<<",\"Frobenius_index\":"<<frobenius[i]<<",\"source_U\":";ak_emit_poly(kernel[i].u);std::cout<<",\"source_V\":";ak_emit_poly(kernel[i].v);std::cout<<",\"target_U\":";ak_emit_poly(images[i].u);std::cout<<",\"target_V\":";ak_emit_poly(images[i].v);std::cout<<",\"principal_cubic\":";ak_emit_row(cubics[i]);std::cout<<",\"rank\":"<<ranks[i]<<'}';}std::cout<<"],\"outside_control\":{\"source_U\":";ak_emit_poly(outside.u);std::cout<<",\"source_V\":";ak_emit_poly(outside.v);std::cout<<",\"target_U\":";ak_emit_poly(control_image.u);std::cout<<",\"target_V\":";ak_emit_poly(control_image.v);std::cout<<"}}\n";
}catch(const std::exception& e){std::cerr<<"REJECT "<<e.what()<<'\n';return 1;}}
